        ('ch7', '(d)', 'class Controller:\n    def __init__(self):\n        # Delta_cl^d = (s + 1)(s + 1.5) = s^2 + 2.5 s + 1.5  (D.7(c))\n        self.kp = 4.5\n        self.kd = 12.0\n\n    def update(self, z_r, x):\n        z = x[0, 0]\n        zdot = x[1, 0]\n        F = self.kp * (z_r - z) - self.kd * zdot   # Fig. 7-2: D on the output\n        return F\n', 'but not with', False),
        ('ch7', '(d)', 'class Controller:\n    def __init__(self):\n        # Delta_cl^d = (s + 1)(s + 1.5) = s^2 + 2.5 s + 1.5  (D.7(c))\n        self.kp = P.m * 1.5 - P.k\n        self.kd = P.m * 2.5 - P.b\n\n    def update(self, z_r, x):\n        z = x[0, 0]\n        zdot = x[1, 0]\n        F = self.kp * (z_r - z) + self.kd * zdot   # Fig. 7-2: D on the output\n        return F\n', 'differs from the design', False),
        ('ch8', '(b)', 'class Controller:\n    def __init__(self):\n        tr = 1.648\n        zeta = 0.7\n        wn = 2.2 / tr\n        self.kp = P.m * wn**2 - P.k\n        self.kd = 2 * P.m * zeta * wn - P.b\n\n    def update(self, z_r, x):\n        z = x[0, 0]\n        zdot = x[1, 0]\n        F = self.kp * (z_r - z) - self.kd * zdot\n        return F\n', 'Saturate its output', False),
