        ('ch10', '(c)', 'class Controller:\n    def __init__(self):\n        tr = 2.0          # the D.8(a) design\n        zeta = 0.7\n        wn = 2.2 / tr\n        self.kp = P.m * wn**2 - P.k\n        self.kd = 2 * P.m * zeta * wn - P.b\n        self.ki = 0.0\n        self.sigma = 0.05\n        self.beta = (2 * self.sigma - P.Ts) / (2 * self.sigma + P.Ts)\n        self.z_dot = P.zdot0\n        self.z_prev = P.z0\n        self.error_prev = 0.0\n        self.integrator = 0.0\n\n    def update(self, z_r, y):\n        z = y[0, 0]\n        error = z_r - z\n        # dirty derivative (Eq. 10.4)\n        self.z_dot = self.beta * self.z_dot + 2 / (2 * self.sigma + P.Ts) * (z - self.z_prev)\n        # anti-windup: integrate only while z_dot is small\n        if abs(self.z_dot) < 0.05:\n            self.integrator += P.Ts / 2 * (error + self.error_prev)\n        F_e = P.k * z_r   # equilibrium force for z_e = z_r (D.4)\n        F = F_e + self.kp * error + self.ki * self.integrator - self.kd * self.z_dot\n        F = max(-P.Fmax, min(P.Fmax, F))\n        self.error_prev = error\n        self.z_prev = z\n        return F\n', 'Error before the switch', False),
        ('ch10', '(c)', 'class Controller:\n    def __init__(self):\n        tr = 2.0          # the D.8(a) design\n        zeta = 0.7\n        wn = 2.2 / tr\n        self.kp = P.m * wn**2 - P.k\n        self.kd = 2 * P.m * zeta * wn - P.b\n        self.ki = 0.75\n        self.sigma = 0.05\n        self.beta = (2 * self.sigma - P.Ts) / (2 * self.sigma + P.Ts)\n        self.z_dot = P.zdot0\n        self.z_prev = P.z0\n        self.error_prev = 0.0\n        self.integrator = 0.0\n\n    def update(self, z_r, y):\n        z = y[0, 0]\n        zdot = y[1, 0]\n        error = z_r - z\n        # dirty derivative (Eq. 10.4)\n        self.z_dot = self.beta * self.z_dot + 2 / (2 * self.sigma + P.Ts) * (z - self.z_prev)\n        # anti-windup: integrate only while z_dot is small\n        if abs(self.z_dot) < 0.05:\n            self.integrator += P.Ts / 2 * (error + self.error_prev)\n        F_e = P.k * z_r   # equilibrium force for z_e = z_r (D.4)\n        F = F_e + self.kp * error + self.ki * self.integrator - self.kd * self.z_dot\n        F = max(-P.Fmax, min(P.Fmax, F))\n        self.error_prev = error\n        self.z_prev = z\n        return F\n', 'IndexError', False),
        ('ch11', '(e)', 'class Controller:\n    def __init__(self):\n        tr = 2.0          # the D.8(a) design\n        zeta = 0.7\n        wn = 2.2 / tr\n        self.kp = P.m * wn**2 - P.k\n        self.kd = 2 * P.m * zeta * wn - P.b\n        self.ki = 0.75\n        self.sigma = 0.05\n        self.beta = (2 * self.sigma - P.Ts) / (2 * self.sigma + P.Ts)\n        self.z_dot = P.zdot0\n        self.z_prev = P.z0\n        self.error_prev = 0.0\n        self.integrator = 0.0\n\n    def update(self, z_r, y):\n        z = y[0, 0]\n        error = z_r - z\n        # dirty derivative (Eq. 10.4)\n        self.z_dot = self.beta * self.z_dot + 2 / (2 * self.sigma + P.Ts) * (z - self.z_prev)\n        # anti-windup: integrate only while z_dot is small\n        if abs(self.z_dot) < 0.05:\n            self.integrator += P.Ts / 2 * (error + self.error_prev)\n        F_e = P.k * z_r   # equilibrium force for z_e = z_r (D.4)\n        F = F_e + self.kp * error + self.ki * self.integrator - self.kd * self.z_dot\n        F = max(-P.Fmax, min(P.Fmax, F))\n        self.error_prev = error\n        self.z_prev = z\n        return F\n', 'differs from the design', False),
        ('ch11', '(e)', 'import control as cnt\n\nclass Controller:\n    def __init__(self):\n        tr = 2.0\n        zeta = 0.7\n        self.A = np.array([[0.0, 1.0], [-P.k / P.m, -P.b / P.m]])\n        self.B = np.array([[0.0], [1 / P.m]])\n        self.C = np.array([[1.0, 0.0]])\n        wn = 2.2 / tr\n        self.K = np.array([[3.05, 7.2]])\n        self.kr = 6.05\n        # dirty derivative for zdot (Eq. 10.4)\n        sigma = 0.05\n        self.beta = (2 * sigma - P.Ts) / (2 * sigma + P.Ts)\n        self.gamma = 2 / (2 * sigma + P.Ts)\n        self.z_prev = P.z0\n        self.z_dot = P.zdot0\n\n    def update(self, z_r, y):\n        z = y[0, 0]\n        self.z_dot = self.beta * self.z_dot + self.gamma * (z - self.z_prev)\n        self.z_prev = z\n        x = np.array([[z], [self.z_dot]])\n        F = -(self.K @ x)[0, 0] + self.kr * z_r\n        return max(-P.Fmax, min(P.Fmax, F))\n', 'but not with', False),
        ('ch11', '(e)', 'class Controller:\n    def __init__(self):\n        tr = 2.0          # the D.8(a) design\n        zeta = 0.7\n        wn = 2.2 / tr\n        self.kp = P.m * wn**2 - P.k\n        self.kd = 2 * P.m * zeta * wn - P.b\n        self.ki = 0.0\n        self.sigma = 0.05\n        self.beta = (2 * self.sigma - P.Ts) / (2 * self.sigma + P.Ts)\n        self.z_dot = P.zdot0\n        self.z_prev = P.z0\n        self.error_prev = 0.0\n        self.integrator = 0.0\n\n    def update(self, z_r, y):\n        z = y[0, 0]\n        error = z_r - z\n        # dirty derivative (Eq. 10.4)\n        self.z_dot = self.beta * self.z_dot + 2 / (2 * self.sigma + P.Ts) * (z - self.z_prev)\n        # anti-windup: integrate only while z_dot is small\n        if abs(self.z_dot) < 0.05:\n            self.integrator += P.Ts / 2 * (error + self.error_prev)\n        F_e = P.k * z_r   # equilibrium force for z_e = z_r (D.4)\n        F = F_e + self.kp * error + self.ki * self.integrator - self.kd * self.z_dot\n        F = max(-P.Fmax, min(P.Fmax, F))\n        self.error_prev = error\n        self.z_prev = z\n        return F\n', 'matches the design', True),
        ('ch12', '(a) Add', 'import control as cnt\n\nclass Controller:\n    def __init__(self):\n        tr = 2.0\n        zeta = 0.7\n        p_I = -1.0\n        self.A = np.array([[0.0, 1.0], [-P.k / P.m, -P.b / P.m]])\n        self.B = np.array([[0.0], [1 / P.m]])\n        self.C = np.array([[1.0, 0.0]])\n        A1 = np.block([[self.A, np.zeros((2, 1))], [-self.C, np.zeros((1, 1))]])\n        B1 = np.vstack([self.B, [[0.0]]])\n        wn = 2.2 / tr\n        K1 = cnt.place(A1, B1, np.roots(np.convolve([1, 2 * zeta * wn, wn**2], [1, -p_I])))\n        self.K = K1[:, 0:2]\n        self.ki = K1[0, 2]\n        self.integrator = 0.0\n        self.error_prev = 0.0\n        sigma = 0.05\n        self.beta = (2 * sigma - P.Ts) / (2 * sigma + P.Ts)\n        self.gamma = 2 / (2 * sigma + P.Ts)\n        self.z_prev = P.z0\n        self.z_dot = P.zdot0\n\n    def update(self, z_r, y):\n        z = y[0, 0]\n        self.z_dot = self.beta * self.z_dot + self.gamma * (z - self.z_prev)\n        self.z_prev = z\n        x = np.array([[z], [self.z_dot]])\n        error = z_r - x[0, 0]\n        integ = self.integrator + P.Ts / 2 * (error + self.error_prev)\n        F = -(self.K @ x)[0, 0] - self.ki * integ\n        # anti-windup: keep the integrator still while F saturates\n        if True:\n            self.integrator = integ\n        self.error_prev = error\n        F = -(self.K @ x)[0, 0] - self.ki * self.integrator\n        return max(-P.Fmax, min(P.Fmax, F))\n', 'winds up', False),
        ('ch12', '(c)', 'import control as cnt\n\nclass Controller:\n    def __init__(self):\n        tr = 2.0\n        zeta = 0.7\n        self.A = np.array([[0.0, 1.0], [-P.k / P.m, -P.b / P.m]])\n        self.B = np.array([[0.0], [1 / P.m]])\n        self.C = np.array([[1.0, 0.0]])\n        wn = 2.2 / tr\n        self.K = cnt.place(self.A, self.B, np.roots([1, 2 * zeta * wn, wn**2]))\n        self.kr = -1.0 / (self.C @ np.linalg.inv(self.A - self.B @ self.K) @ self.B)[0, 0]\n        # dirty derivative for zdot (Eq. 10.4)\n        sigma = 0.05\n        self.beta = (2 * sigma - P.Ts) / (2 * sigma + P.Ts)\n        self.gamma = 2 / (2 * sigma + P.Ts)\n        self.z_prev = P.z0\n        self.z_dot = P.zdot0\n\n    def update(self, z_r, y):\n        z = y[0, 0]\n        self.z_dot = self.beta * self.z_dot + self.gamma * (z - self.z_prev)\n        self.z_prev = z\n        x = np.array([[z], [self.z_dot]])\n        F = -(self.K @ x)[0, 0] + self.kr * z_r\n        return max(-P.Fmax, min(P.Fmax, F))\n', 'Error before the switch', False),
